//--------------------------------------------------------------------------//

Boolean out_state_offset( Out out )
{
    if ( ++out->time >= out->frame.t_offset )
    {
        out->time  = 0 ; 
        
        out->state = (Out_State)out_state_on ;
        
       if( out->out_func )
	   {
	   		(out->out_func)( TRUE ,out); 
	   }		        
    }
    
    return FALSE ; 
}

//--------------------------------------------------------------------------//

Boolean out_state_on( Out out )
{
    if( ++out->time >= out->frame.t_on )
    {
        out->time  = 0 ; 
        
        out->state = (Out_State)out_state_off ;

        if( out->out_func )
		{
			(out->out_func)( FALSE ,out); 
		}
    }
    return FALSE ; 
}

//--------------------------------------------------------------------------//

Boolean out_state_off( Out out )
{
    if( ++out->time >= out->frame.t_off )
    {        
        if((++out->pulse == out->frame.pulse) && out->frame.pulse )
        {            
            out->state = (Out_State)NULL;   
                        
            return TRUE ; 
        }
        else
        {
            out->time  = 0 ; 
                                    
            out->state = (Out_State)out_state_on ;
            
            if( out->out_func )
			{
				(out->out_func)( TRUE ,out);                                 
			}
        }
    }
            
    return FALSE ; 
}

//--------------------------------------------------------------------------//

